138	            .map((k) => build(k, depth + 1));
139	    const kind = toolKindOf(call, kids.length > 0);
140	    return {
141	      call,
142	      kind,
143	      meta: metaFor(call, kind),
144	      children: kids,
145	      running: call.status === "running",
146	      report: kind === "subagent" ? (call.agent?.summary ?? call.output) : null,
147	    };
148	  };
149	
150	  return roots
151	    .filter((c) => !visited.has(c.id))
152	    .sort((a, b) => a.startedAt - b.startedAt)
153	    .map((c) => build(c, 0));
154	}
155	
156	// task_* events carry the richest data, but they only exist on claude runs
157	// that got far enough. The Agent tool's own input has the same three fields,
158	// so a denied / non-claude call still renders with a label.
159	function metaFor(call: ToolCall, kind: ToolKind): TaskMeta {
160	  const input = (call.input ?? {}) as Record<string, unknown>;
161	  const fromInput: TaskMeta = {
162	    subagentType:
163	      typeof input.subagent_type === "string" ? input.subagent_type : undefined,
164	    description:
165	      typeof input.description === "string" ? input.description : undefined,
166	    prompt: typeof input.prompt === "string" ? input.prompt : undefined,
167	  };
168	  const merged: TaskMeta = {
169	    ...fromInput,
170	    ...stripUndefined(call.agent ?? {}),
171	    // description is live-updated by task_progress to the *current step*
172	    // ("Running ls" / "Beta: beta-1"), which is useful while running but a
173	    // poor label once finished — the original ask is what you want to read
174	    // afterwards.
175	    description:
176	      call.status === "running"
177	        ? (call.agent?.description ?? fromInput.description)
178	        : (fromInput.description ?? call.agent?.description),
179	  };
180	  if (kind === "workflow") {
181	    if (!merged.description) merged.description = merged.workflowName;
182	    // The CLI puts the whole script in task_started's `prompt`, but a run that
183	    // never got that far (or a non-claude backend) still has it in the tool
184	    // input — under `script`, or on disk at `scriptPath` for a resume.
185	    if (!merged.prompt) {
186	      merged.prompt =
187	        (typeof input.script === "string" ? input.script : undefined) ??
188	        (typeof input.scriptPath === "string" ? input.scriptPath : undefined);
189	    }
190	  }
191	  return merged;
192	}
193	
194	function stripUndefined(m: TaskMeta): TaskMeta {
195	  const out: TaskMeta = {};
196	  for (const [k, v] of Object.entries(m)) {
197	    if (v !== undefined) (out as Record<string, unknown>)[k] = v;
198	  }
199	  return out;
200	}
201	
202	/** Label for a sub-agent: "general-purpose" / "Explore" / fallback. */
203	export function subagentLabel(meta: TaskMeta): string {
204	  return meta.subagentType?.trim() || "子 Agent";
205	}
206	
207	/** Depth-first walk, parents before children. */
208	export function walkToolTree(nodes: ToolNode[]): ToolNode[] {
209	  const out: ToolNode[] = [];
210	  const push = (n: ToolNode) => {
211	    out.push(n);
212	    for (const c of n.children) push(c);
213	  };
214	  for (const n of nodes) push(n);
215	  return out;
216	}
217	
218	export type ToolTreeCounts = {
219	  /** Every call in the tree, nested ones included. */
220	  total: number;
221	  subagents: number;
222	  workflows: number;
223	  running: number;
224	  errors: number;
225	};
226	
227	export function countToolTree(nodes: ToolNode[]): ToolTreeCounts {
228	  const all = walkToolTree(nodes);
229	  return {
230	    total: all.length,
