132	// "Read ×5 · Edit ×3 · Bash" — tool names in first-appearance order.
133	function segmentSummary(nodes: ToolNode[]): string {
134	  const counts = new Map<string, number>();
135	  for (const n of nodes) {
136	    const t = toolTitle(n.call);
137	    counts.set(t, (counts.get(t) ?? 0) + 1);
138	  }
139	  const names = [...counts.entries()].map(([t, c]) =>
140	    c > 1 ? `${t} ×${c}` : t,
141	  );
142	  return names.slice(0, 4).join(" · ") + (names.length > 4 ? " …" : "");
143	}
144	
145	// Only worth a number when the run actually took time — a pile of instant
146	// reads summing to 80ms is noise.
147	function segmentDuration(nodes: ToolNode[]): string {
148	  const ms = nodes.reduce((s, n) => s + (n.call.durationMs ?? 0), 0);
149	  return ms >= 1000 ? formatDuration(ms) : "";
150	}
151	
152	// One standalone row. Recursive: a sub-agent's own calls render as a nested
153	// TimelineList one level in, so nesting depth costs nothing to support.
154	
155	export function ToolRow({
156	  node,
157	  live,
158	  depth = 0,
159	  currentTodo = false,
160	}: {
161	  node: ToolNode;
162	  live: boolean;
163	  depth?: number;
164	  currentTodo?: boolean;
165	}) {
166	  // null = "follow the automatic rule"; once the user clicks, their choice
167	  // sticks even when the automatic rule would flip (e.g. the sub-agent they
168	  // just collapsed starts another tool).
169	  const [userOpen, setUserOpen] = useState<boolean | null>(null);
170	  const open = userOpen ?? rowAutoOpen(node, live, currentTodo);
171	
172	  const view = resolveToolView(node);
173	  const useCustom = view?.canRender(node) ?? false;
174	  const Body = useCustom ? view!.Component : RawView;
175	
176	  const elapsed = useElapsed(live && node.running ? node.call.startedAt : null);
177	  const nestedErrors = node.kind === "tool" ? 0 : nestedErrorCount(node);
178	
179	  return (
180	    <div className="bg-surface/60">
181	      <button
182	        type="button"
183	        onClick={() => setUserOpen(!open)}
184	        aria-expanded={open}
185	        className="w-full px-3 py-2 flex items-center gap-2 text-ui text-left hover:bg-surface-muted/60 transition-colors"
186	      >
187	        <span
188	          className="text-ink-faint transition-transform shrink-0"
189	          style={{ transform: open ? "rotate(90deg)" : "rotate(0)" }}
190	          aria-hidden
191	        >
192	          ▸
193	        </span>
194	        <StatusPill node={node} live={live} />
195	        <span className="shrink-0 select-none text-ink-faint" aria-hidden>
196	          {rowIcon(node)}
197	        </span>
198	        <span className="font-mono text-ink shrink-0">{rowTitle(node)}</span>
199	        <span className="text-ink-muted truncate min-w-0">
200	          {rowSummary(node) ?? ""}
201	        </span>
202	        <span className="flex-1" />
203	        {nestedErrors > 0 && (
204	          // 收着的委派行也得把肚子里的失败招出来 —— 折叠不是藏错的理由。
205	          <span className="text-nano text-danger-ink shrink-0">
206	            {nestedErrors} 失败
207	          </span>
208	        )}
209	        <span className="text-nano tabular-nums text-ink-faint shrink-0">
210	          {statLine(node, elapsed)}
211	        </span>
212	      </button>
213	
214	      {open && (
