259	      if (!container) return;
260	      const containerTop = container.getBoundingClientRect().top;
261	      // Cards are in thread order, tops strictly increasing: the LAST card
262	      // whose top is at/above the viewport top is the one being read. When
263	      // every card is below the top (scrolled to the very start), fall back
264	      // to the first card at offset 0.
265	      let picked: { nodeId: string; offset: number } | null = null;
266	      for (const n of threadData.thread) {
267	        const cardEl = roundRefs.current.get(n.id);
268	        if (!cardEl) continue;
269	        const top = cardEl.getBoundingClientRect().top - containerTop;
270	        if (top <= 1) {
271	          picked = { nodeId: n.id, offset: Math.max(0, -top) };
272	        } else {
273	          if (!picked) picked = { nodeId: n.id, offset: 0 };
274	          break;
275	        }
276	      }
277	      if (picked) setReadingPosition(sid, picked);
